  "jb.so.snag.done": ["Snag logged on {job}. It is on the snag list.", "Mangel bei {job} erfasst. Er steht auf der Mängelliste.", "Réserve notée sur {job}. Elle est dans la liste des réserves.", "Mangel noteret på {job}. Den står på mangellisten.", "Vada u {job} zapsána. Je v seznamu vad.", "已在 {job} 登记整改项。已列入整改清单。", "已在 {job} 登記改善項。已列入改善清單。", "سُجّلت ملاحظة على {job}. إنها في قائمة الملاحظات."],
  "jb.so.snag.stops.done": ["Snag logged on {job}. It stops the sign-off until it is put right.", "Mangel bei {job} erfasst. Er verhindert die Abnahme, bis er behoben ist.", "Réserve notée sur {job}. Elle bloque la réception jusqu’à ce qu’elle soit levée.", "Mangel noteret på {job}. Den stopper godkendelsen, indtil den er udbedret.", "Vada u {job} zapsána. Brání převzetí, dokud se neodstraní.", "已在 {job} 登记整改项。整改完成前将阻止验收。", "已在 {job} 登記改善項。改善完成前將阻止驗收。", "سُجّلت ملاحظة على {job}. تمنع الاستلام حتى تُعالج."],
  "jb.so.photos": ["Photos of the finished work", "Fotos der fertigen Arbeit", "Photos du travail fini", "Fotos af det færdige arbejde", "Fotky hotové práce", "完工照片", "完工照片", "صور العمل المنجز"],
  "jb.so.photos.later": ["Photos are taken on the crew's phone when the job is signed off.", "Fotos werden bei der Abnahme mit dem Telefon des Teams gemacht.", "Les photos sont prises avec le téléphone de l’équipe à la réception.", "Fotos tages på holdets telefon, når opgaven godkendes.", "Fotky se pořizují telefonem čety při převzetí.", "验收时用班组手机拍照。", "驗收時用班組手機拍照。", "تُلتقط الصور بهاتف الفريق عند الاستلام."],
  "jb.so.photos.none": ["No photos are held for this sign-off.", "Zu dieser Abnahme gibt es keine Fotos.", "Aucune photo n’est conservée pour cette réception.", "Der er ingen fotos til denne godkendelse.", "K tomuto převzetí nejsou žádné fotky.", "此次验收没有照片。", "此次驗收沒有照片。", "لا صور محفوظة لهذا الاستلام."],
  "jb.so.who": ["Who signed", "Wer unterschrieben hat", "Qui a signé", "Hvem skrev under", "Kdo podepsal", "签字人", "簽名人", "من وقّع"],
  "jb.so.signedOn": ["signed {day}", "unterschrieben am {day}", "signé le {day}", "underskrevet {day}", "podepsáno {day}", "{day} 签字", "{day} 簽名", "وقّع {day}"],
  "jb.so.signature.alt": ["Signature of {name}", "Unterschrift von {name}", "Signature de {name}", "Underskrift fra {name}", "Podpis: {name}", "{name} 的签字", "{name} 的簽名", "توقيع {name}"],
  "jb.so.signature.none": ["No drawn signature is held for this sign-off.", "Zu dieser Abnahme gibt es keine gezeichnete Unterschrift.", "Aucune signature dessinée n’est conservée pour cette réception.", "Der er ingen tegnet underskrift til denne godkendelse.", "K tomuto převzetí není uložen žádný kreslený podpis.", "此次验收没有手写签名。", "此次驗收沒有手寫簽名。", "لا توقيع مرسوم محفوظ لهذا الاستلام."],
  "jb.so.copy": ["A copy went to {to}.", "Eine Kopie ging an {to}.", "Une copie a été envoyée à {to}.", "En kopi gik til {to}.", "Kopie odešla na {to}.", "副本已发送至 {to}。", "副本已寄至 {to}。", "أُرسلت نسخة إلى {to}."],
  "jb.so.sealed": [
    "A sign-off stays as it was made: nobody changes it. A correction would be a new sign-off that names this one.",
    "Eine Abnahme bleibt, wie sie gemacht wurde: Niemand ändert sie. Eine Berichtigung wäre eine neue Abnahme, die diese nennt.",
    "Une réception reste telle qu’elle a été faite : personne ne la modifie. Une correction serait une nouvelle réception qui cite celle-ci.",
    "En godkendelse forbliver, som den blev lavet: ingen ændrer den. En rettelse vil være en ny godkendelse, der henviser til denne.",
    "Převzetí zůstává, jak bylo uděláno: nikdo ho nemění. Oprava by byla nové převzetí, které na toto odkazuje.",
    "验收一经签署即保持原样：任何人都不能修改。更正会是一份引用此验收的新验收。",
    "驗收一經簽署即保持原樣：任何人都不能修改。更正會是一份引用此驗收的新驗收。",
    "يبقى الاستلام كما أُنجز: لا أحد يغيّره. التصحيح يكون استلامًا جديدًا يشير إلى هذا.",
  ],
  "jb.so.stopped": ["“{what}” is open and stops the sign-off. Put it right first.", "„{what}“ ist offen und verhindert die Abnahme. Zuerst beheben.", "« {what} » est ouverte et bloque la réception. Levez-la d’abord.", "“{what}” er åben og stopper godkendelsen. Udbedr den først.", "„{what}“ je otevřená a brání převzetí. Nejdřív ji odstraňte.", "“{what}”尚未整改，会阻止验收。请先整改。", "「{what}」尚未改善，會阻止驗收。請先改善。", "«{what}» قائمة وتمنع الاستلام. عالجها أولًا."],
  "jb.so.onPhone": ["The customer signs on the crew's phone at the end of the job.", "Die Kundschaft unterschreibt am Ende des Auftrags auf dem Telefon des Teams.", "Le client signe sur le téléphone de l’équipe à la fin du chantier.", "Kunden skriver under på holdets telefon, når opgaven er færdig.", "Zákazník podepisuje na telefonu čety na konci zakázky.", "工单结束时，客户在班组手机上签字。", "工單結束時，客戶在班組手機上簽名。", "يوقّع العميل على هاتف الفريق في نهاية العمل."],
  "jb.so.later": ["Signing on this screen, with the signature drawn here, is not available yet.", "Unterschreiben auf diesem Bildschirm, mit hier gezeichneter Unterschrift, ist noch nicht möglich.", "Signer sur cet écran, avec une signature dessinée ici, n’est pas encore possible.", "At skrive under på denne skærm, med underskriften tegnet her, er ikke muligt endnu.", "Podepsat na této obrazovce, s podpisem nakresleným zde, zatím nejde.", "暂时还不能在此页面上手写签名。", "暫時還不能在此頁面上手寫簽名。", "التوقيع على هذه الشاشة برسمه هنا غير متاح بعد."],
